alter type public.qgang_role add value if not exists 'guest';
alter table public.profiles alter column role set default 'guest'::public.qgang_role;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ declare base_handle text; begin base_handle:=lower(regexp_replace(coalesce(new.raw_user_meta_data->>'user_name',new.raw_user_meta_data->>'name','qganger'),'[^a-zA-Z0-9_]','','g')); if char_length(base_handle)<3 then base_handle:='qganger'; end if; insert into public.profiles(id,handle,display_name,role) values(new.id,left(base_handle,18)||'_'||substr(replace(new.id::text,'-',''),1,5),coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name','Q-GANG Kullanıcısı'),'guest'); return new; end$$;
